export class Fluid {
  constructor(w=96,h=60) {
    this.w=w;this.h=h;this.stride=w+2;this.size=(w+2)*(h+2);
    for(const k of ['u','v','u0','v0','p','p0','div'])this[k]=new Float32Array(this.size);
  }
  boundary(a,type=0) {
    const {w,h,stride:s}=this;
    for(let x=1;x<=w;x++){a[x]=type===2?-a[s+x]:a[s+x];a[(h+1)*s+x]=type===2?-a[h*s+x]:a[h*s+x];}
    for(let y=1;y<=h;y++){a[y*s]=type===1?-a[y*s+1]:a[y*s+1];a[y*s+w+1]=type===1?-a[y*s+w]:a[y*s+w];}
    a[0]=(a[1]+a[s])*.5;a[w+1]=(a[w]+a[w+1+s])*.5;
    a[(h+1)*s]=(a[h*s]+a[(h+1)*s+1])*.5;a[(h+1)*s+w+1]=(a[h*s+w+1]+a[(h+1)*s+w])*.5;
  }
  sample(a,x,y){const s=this.stride;x=clamp(x,.5,this.w+.5);y=clamp(y,.5,this.h+.5);const i=Math.floor(x),j=Math.floor(y),u=x-i,v=y-j,k=j*s+i;return (a[k]*(1-u)+a[k+1]*u)*(1-v)+(a[k+s]*(1-u)+a[k+s+1]*u)*v;}
  project(iterations=20) {
    const {w,h,stride:s,u,v,div}=this;this.p.fill(0);this.p0.fill(0);
    for(let y=1;y<=h;y++)for(let x=1;x<=w;x++){const i=y*s+x;div[i]=-.5*(u[i+1]-u[i-1]+v[i+s]-v[i-s]);}
    this.boundary(div);
    for(let k=0;k<iterations;k++){
      const p=this.p,q=this.p0;
      for(let y=1;y<=h;y++)for(let x=1;x<=w;x++){const i=y*s+x;q[i]=(div[i]+p[i-1]+p[i+1]+p[i-s]+p[i+s])*.25;}
      this.boundary(q);this.p=q;this.p0=p;
    }
    for(let y=1;y<=h;y++)for(let x=1;x<=w;x++){const i=y*s+x;u[i]-=.5*(this.p[i+1]-this.p[i-1]);v[i]-=.5*(this.p[i+s]-this.p[i-s]);}
    this.boundary(u,1);this.boundary(v,2);
  }
  step(dt,damping=.6) {
    this.u0.set(this.u);this.v0.set(this.v);const {w,h,stride:s}=this;
    const decay=Math.exp(-damping*dt);
    for(let y=1;y<=h;y++)for(let x=1;x<=w;x++){const i=y*s+x,px=x-dt*this.u0[i],py=y-dt*this.v0[i];this.u[i]=this.sample(this.u0,px,py)*decay;this.v[i]=this.sample(this.v0,px,py)*decay;}
    this.boundary(this.u,1);this.boundary(this.v,2);this.project();
  }
  splat(x,y,dx,dy,radius=.14) {
    for(let j=1;j<=this.h;j++)for(let i=1;i<=this.w;i++) {
      const r2=((i/this.w-x)**2+(j/this.h-y)**2)/(radius*radius),f=Math.exp(-r2*3);
      if(f<.001)continue;const k=j*this.stride+i;
      this.u[k]=clamp(this.u[k]+dx*this.w*f*12,-170,170);this.v[k]=clamp(this.v[k]+dy*this.h*f*12,-170,170);
    }
  }
  divergenceEnergy(){let v=0;const s=this.stride;for(let y=2;y<this.h;y++)for(let x=2;x<this.w;x++){const i=y*s+x;v+=(this.u[i+1]-this.u[i-1]+this.v[i+s]-this.v[i-s])**2;}return v;}
}
export async function create(stage,controls) {
  const W=432,H=270,fluid=new Fluid(),small=offscreen(W,H),cx=small.getContext('2d');
  let original=await image(asset('studies/tidal-garden.png')),dye=new Float32Array(W*H*4),next=new Float32Array(dye.length),output=new ImageData(W,H),damping=.6;
  let steps=0,acc=0,last=null,sourceName='原创矢量画 · 潮汐花园',generation=0;
  function reset(){dye.set(sampleImage(original,W,H).data);for(const k of ['u','v','u0','v0','p','p0','div'])fluid[k].fill(0);steps=0;acc=0;stage.dirty=true;}
  reset();
  range(controls,'动量衰减',.1,2,.6,.1,v=>damping=v);
  button(controls,'轻推颜料',()=>{fluid.splat(.35,.54,.08,-.045);fluid.splat(.66,.43,-.06,.05);stage.dirty=true;});
  fileInput(controls,'换一张图片','image/png,image/jpeg,image/webp',16,async file=>{const ticket=++generation,url=URL.createObjectURL(file);try{const img=await image(url);if(ticket!==generation)return;original=img;sourceName=file.name;reset();}finally{URL.revokeObjectURL(url);}});
  function transport(dt) {
    fluid.step(dt,damping);
    for(let y=0;y<H;y++)for(let x=0;x<W;x++){
      const vx=fluid.sample(fluid.u,x/W*fluid.w+.5,y/H*fluid.h+.5),vy=fluid.sample(fluid.v,x/W*fluid.w+.5,y/H*fluid.h+.5);
      const sx=clamp(x-vx*dt*W/fluid.w,0,W-1),sy=clamp(y-vy*dt*H/fluid.h,0,H-1),a=Math.floor(sx),b=Math.floor(sy),u=sx-a,v=sy-b;
      const p=(b*W+a)*4,q=(b*W+Math.min(W-1,a+1))*4,r=(Math.min(H-1,b+1)*W+a)*4,s=(Math.min(H-1,b+1)*W+Math.min(W-1,a+1))*4,k=(y*W+x)*4;
      for(let ch=0;ch<3;ch++)next[k+ch]=(dye[p+ch]*(1-u)+dye[q+ch]*u)*(1-v)+(dye[r+ch]*(1-u)+dye[s+ch]*u)*v;
      next[k+3]=255;
    }
    [dye,next]=[next,dye];steps++;
  }
  return {reset,pointer(p){if(!p.down){last=null;return;}const q=sourcePointer(p,W,H,stage.width,stage.height);if(last)fluid.splat(q.x,q.y,q.x-last[0],q.y-last[1]);last=[q.x,q.y];},release(){last=null;},
    render(dt){acc+=dt;let n=0;while(acc>=1/60&&n<3){transport(1/60);acc-=1/60;n++;}if(n===3)acc=0;
      output.data.set(dye);cx.putImageData(output,0,0);stage.ctx.imageSmoothingEnabled=true;const fit=coverFit(W,H,stage.width,stage.height);stage.ctx.drawImage(small,fit.x,fit.y,fit.width,fit.height);
      if(stage.pointer.down){stage.ctx.strokeStyle='#f5edd496';stage.ctx.lineWidth=1;stage.ctx.beginPath();stage.ctx.arc(stage.pointer.x*stage.width,stage.pointer.y*stage.height,24,0,Math.PI*2);stage.ctx.stroke();}
      caption(stage.ctx,'DRAG THE PIGMENT / 松手后继续流动',22,stage.height-22,'#fbf0d3');
      stage.status(`${sourceName} · 压力投影 + 颜料输运 · ${steps} 步 · 不会自动复原`);
    },inspect:()=>({steps,grid:[fluid.w,fluid.h],dyeSize:[W,H],divergence:fluid.divergenceEnergy(),finite:fluid.u.every(Number.isFinite)&&dye.every(Number.isFinite)}),dispose(){generation++;}};
}
import {clamp,lensRay} from './math.mjs';
import {asset,image,sampleImage,offscreen,range,fileInput,caption,bilinear,coverFit,sourcePointer} from './core.mjs';
export async function create(stage,controls) {
  const W=600,H=375,small=offscreen(W,H),cx=small.getContext('2d');
  let artwork=await image(asset('studies/quiet-orbit.png')),src=sampleImage(artwork,W,H),output=new ImageData(W,H);
  let ior=1.46,dispersion=.018,radius=98,pos=[.5,.51],lut=[],generation=0,sourceName='原创矢量画 · 静谧轨道';
  function build(){lut=[];for(let y=-radius;y<=radius;y++)for(let x=-radius;x<=radius;x++)if(x*x+y*y<radius*radius){const rays=[ior-dispersion,ior,ior+dispersion].map(n=>lensRay(x/radius,y/radius,n));if(rays[1])lut.push({x,y,rays});}stage.dirty=true;}
  range(controls,'折射率',1.05,1.8,ior,.01,v=>{ior=v;build();});
  range(controls,'色散',0,.055,dispersion,.001,v=>{dispersion=v;build();});
  range(controls,'镜体尺寸',65,132,radius,1,v=>{radius=v;build();});
  fileInput(controls,'更换背景图','image/png,image/jpeg,image/webp',16,async file=>{const ticket=++generation,url=URL.createObjectURL(file);try{const img=await image(url);if(ticket!==generation)return;artwork=img;src=sampleImage(artwork,W,H);sourceName=file.name;stage.dirty=true;}finally{URL.revokeObjectURL(url);}});
  build();
  return {static:true,reset(){pos=[.5,.51];stage.dirty=true;},pointer(p){if(p.down){const q=sourcePointer(p,W,H,stage.width,stage.height);pos=[clamp(q.x,.14,.86),clamp(q.y,.22,.78)];}},
    render(){
      output.data.set(src.data);const centerX=Math.round(pos[0]*W),centerY=Math.round(pos[1]*H);
      for(const e of lut){const x=centerX+e.x,y=centerY+e.y;if(x<0||y<0||x>=W||y>=H)continue;const k=(y*W+x)*4,nx=e.x/radius,ny=e.y/radius,nz=Math.sqrt(1-nx*nx-ny*ny);
        const highlight=Math.exp(-((nx+.36)**2+(ny+.45)**2)*95)*180+Math.exp(-((nx-.64)**2+(ny-.31)**2)*150)*80;
        for(let ch=0;ch<3;ch++){
          const ray=e.rays[ch];if(!ray){output.data[k+ch]=195;continue;}
          const c=bilinear(src.data,W,H,centerX+ray.x*radius,centerY+ray.y*radius,ch);
          const absorb=Math.exp(-ray.length*[.018,.009,.005][ch]);
          output.data[k+ch]=c*absorb*(1-ray.fresnel)+[172,202,207][ch]*ray.fresnel+highlight*(.3+.7*nz);
        }output.data[k+3]=255;
      }
      cx.putImageData(output,0,0);const {ctx,width:w,height:h}=stage;const fit=coverFit(W,H,w,h);ctx.drawImage(small,fit.x,fit.y,fit.width,fit.height);
      ctx.save();ctx.translate(fit.x,fit.y);ctx.scale(fit.scale,fit.scale);ctx.strokeStyle='#d7eadb72';ctx.lineWidth=.8;ctx.beginPath();ctx.arc(centerX,centerY,radius,0,Math.PI*2);ctx.stroke();ctx.restore();
      caption(ctx,'SNELL / FRESNEL / DISPERSION',22,h-24,'#f2e8c8');
      stage.status(`${sourceName} · 双界面折射 · RGB 分波长采样 · 拖动玻璃球`);
    },inspect:()=>({ior,dispersion,radius,samples:lut.length,pos,model:'two-interface-sphere'}),dispose(){generation++;}};
}
import {shadowSolid,camera,box,renderFaces,clamp} from './math.mjs';
import {range,button,sky,caption} from './core.mjs';
export async function create(stage,controls) {
  const solid=shadowSolid(27);let angle=0,orbit=.64;
  const input=range(controls,'光源方位',0,90,0,1,v=>{angle=v*Math.PI/180;stage.dirty=true;});
  button(controls,'对齐月影 · 0°',()=>{angle=0;input.value=0;stage.dirty=true;});
  button(controls,'对齐菱影 · 90°',()=>{angle=Math.PI/2;input.value=90;stage.dirty=true;});
  const orbitInput=range(controls,'观察雕塑',-170,170,37,1,v=>{orbit=v*Math.PI/180;stage.dirty=true;});
  const pedestal=box([0,-1.2,0],[2.5,.35,2.5],'#3e545a');
  return {static:true,reset(){angle=0;orbit=.64;input.value=0;orbitInput.value=37;},
    render(){const {ctx,width:w,height:h}=stage;sky(ctx,w,h);
      const mobile=w<640,leftW=mobile?w:w*.51,leftH=mobile?h*.53:h;
      ctx.save();ctx.beginPath();ctx.rect(0,0,leftW,leftH);ctx.clip();
      const cam=camera([Math.sin(orbit)*5,2.3,Math.cos(orbit)*5],[0,-.1,0],leftW,leftH,.96);
      renderFaces(ctx,[...pedestal,...solid.faces],cam,{light:[Math.sin(angle),.3,Math.cos(angle)]});
      caption(ctx,'ONE SOLID / 同一个三维实体',20,30);
      caption(ctx,`${solid.voxels.length} VOXELS · 固定形体，不换模型`,20,leftH-24,'#93aaa9',10);ctx.restore();
      const wallX=mobile?0:leftW,wallY=mobile?leftH:0,wallW=mobile?w:w-leftW,wallH=mobile?h-leftH:h;
      ctx.save();ctx.beginPath();ctx.rect(wallX,wallY,wallW,wallH);ctx.clip();
      const g=ctx.createRadialGradient(wallX+wallW*.5,wallY+wallH*.47,10,wallX+wallW*.5,wallY+wallH*.47,wallW*.8);g.addColorStop(0,'#ede4ca');g.addColorStop(1,'#a6ac9f');ctx.fillStyle=g;ctx.fillRect(wallX,wallY,wallW,wallH);
      const scale=Math.min(wallW,wallH)*.30,cx=wallX+wallW/2,cy=wallY+wallH*.5;
      // Orthographic directional-light projection of the SAME mesh used on the left.
      // At 0° it projects X/Y; at 90° it projects Z/Y. No target silhouette is painted.
      ctx.fillStyle='#1b2e30';
      ctx.beginPath();
      for(const f of solid.faces){let p=f.points.map(p=>[cx+(p[0]*Math.cos(angle)+p[2]*Math.sin(angle))*scale,cy-p[1]*scale]);
        const area=p.reduce((sum,v,i)=>{const q=p[(i+1)%p.length];return sum+v[0]*q[1]-q[0]*v[1];},0);
        if(Math.abs(area)<1e-8)continue;if(area<0)p.reverse();
        p.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();}
      ctx.fill('nonzero');
      caption(ctx,'PROJECTED LIGHT / 平行光投影',wallX+20,wallY+30,'#304945');
      caption(ctx,`${Math.round(angle/Math.PI*180)}°  ·  ${angle<.035?'月牙':angle>1.535?'菱形':'过渡投影'}`,wallX+20,wallY+wallH-24,'#304945');ctx.restore();
      stage.status('形体 = 月牙轮廓挤出体 ∩ 菱形轮廓挤出体 · 只移动光源，不替换影子');
    },inspect:()=>({angle,voxels:solid.voxels.length,faces:solid.faces.length,model:'fixed-intersection-solid'})};
}
import {foldingPanels,face,imageQuad,camera,renderFaces,mix,clamp,sub,cross,unit,add,mul,dot} from './math.mjs';
import {asset,image,offscreen,range,button,sky,caption} from './core.mjs';
export async function create(stage,controls) {
  const art=await image(asset('studies/paper-world.png'));
  const textures=[0,1,2].map(i=>{const c=offscreen(320,600);c.getContext('2d').drawImage(art,i*art.width/3,0,art.width/3,art.height,0,0,320,600);return c;});
  let open=.76,target=.76,orbit=.36,auto=false;
  const input=range(controls,'展开程度',0,100,76,1,v=>{target=v/100;auto=false;stage.dirty=true;});
  button(controls,'合拢 / 展开',()=>{target=target>.4?0:1;auto=false;stage.dirty=true;});
  const orbitInput=range(controls,'观察角度',-65,65,21,1,v=>{orbit=v*Math.PI/180;stage.dirty=true;});
  button(controls,'自动开合',()=>{auto=!auto;stage.setPlaying(true);});
  function mapPanel(points,u,v){return points[0].map((_,i)=>mix(mix(points[0][i],points[1][i],u),mix(points[3][i],points[2][i],u),v));}
  return {reset(){open=target=.76;orbit=.36;auto=false;input.value=76;orbitInput.value=21;},key(key){if(key==='ArrowUp')target=clamp(target+.05);if(key==='ArrowDown')target=clamp(target-.05);},
    render(dt){if(auto&&dt)target=(1-Math.cos(stage.t*.65))*.5;open=dt?mix(open,target,1-Math.exp(-dt*4)):target;input.value=Math.round(open*100);
      const p=foldingPanels(open),faces=[];const {ctx,width:w,height:h}=stage;const cam=camera([Math.sin(orbit)*6.4,mix(.1,2.8,open),Math.cos(orbit)*6.4],[0,-.65,mix(0,.6,open)],w,h,1.07);
      for(const [key,index] of [['left',0],['center',1],['right',2]]){
        
        const normal=unit(cross(sub(p[key][1],p[key][0]),sub(p[key][2],p[key][0])));
        const back=p[key].map(v=>add(v,mul(normal,-.009)));
        if(dot(normal,sub(cam.eye,p[key][0]))>0)faces.push(...imageQuad([p[key][3],p[key][2],p[key][1],p[key][0]],textures[index],8,7));else faces.push(face(back,'#bda987')); 
        for(let i=0;i<4;i++)faces.push(face([p[key][i],p[key][(i+1)%4],back[(i+1)%4],back[i]],'#dfd1ad'));
      }
      for(let y=0;y<16;y++)for(let x=0;x<8;x++){const q=[[x/8,y/16],[(x+1)/8,y/16],[(x+1)/8,(y+1)/16],[x/8,(y+1)/16]].map(uv=>mapPanel(p.floor,...uv));faces.push(face(q,'#cec8ab',{seamless:true}));}
      // Fold lines and an attached popup arch lie on / hinge from the floor.
      for(let i=1;i<8;i++){const v=i/8,a=mapPanel(p.floor,0,v),b=mapPanel(p.floor,1,v),c=mapPanel(p.floor,1,v+.005),d=mapPanel(p.floor,0,v+.005);faces.push(face([a,b,c,d],'#aaa98f'));}
      const archAt=(u,v)=>mapPanel(p.popup,u,v);
      for(const [u0,u1] of [[0,.13],[.87,1]])faces.push(face([archAt(u0,0),archAt(u1,0),archAt(u1,.55),archAt(u0,.55)],'#ead6a5',{stroke:'#baa47a'}));
      for(let i=0;i<18;i++){
        const a=i/18*Math.PI,b=(i+1)/18*Math.PI;
        const outer=t=>archAt(.5+.5*Math.cos(t),.55+.45*Math.sin(t));
        const inner=t=>archAt(.5+.37*Math.cos(t),.55+.33*Math.sin(t));
        faces.push(face([outer(a),outer(b),inner(b),inner(a)],'#ead6a5',{stroke:'#baa47a'}));
      }
      sky(ctx,w,h,'#294044','#10212a');
      const glow=ctx.createRadialGradient(w/2,h*.48,20,w/2,h*.48,h*.6);glow.addColorStop(0,'#d9b67f1c');glow.addColorStop(1,'#d9b67f00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
      
      renderFaces(ctx,faces,cam);
      caption(ctx,'PAPER KINEMATICS / 边缘相连的折叠结构',22,h-24);
      stage.status(`展开 ${Math.round(open*100)}% · 连续三联画 + 铰接地板 + 立体拱门 · 非 PNG 分层平移`);
    },inspect:()=>({open,target,panels:foldingPanels(open),model:'connected-hinge-net'})};
}

