@media(max-width:600px){.study-footer{grid-template-columns:60px minmax(0,1fr) 62px;gap:9px;padding-inline:0}.study-app>.study-footer{position:fixed;bottom:0;left:12px;right:12px;z-index:15;height:126px;background:linear-gradient(#090c13f2,#090c13 30%);backdrop-filter:blur(18px);border-top:1px solid #e6e0d21a}.study-strip{grid-template-columns:repeat(var(--scene-count),92px);gap:12px}.study-strip .hall-thumb{height:43px}.study-footer .hall-transport button{width:29px}.study-card:focus-visible{outline-offset:-2px}}
